"""Exhaustive small-scale audit of the twist ring Z[t]/(t^2 - 1).

This demo verifies, by brute force over a box of elements, the structural
theorems of the twist ring:

  1. multiplicativity of the norm N(a + bt) = a^2 - b^2;
  2. the unit group is exactly {1, -1, t, -t}, a Klein four-group;
  3. zero divisors are exactly the elements of norm 0, i.e. a = +-b;
  4. no element has norm +-2 (the parity obstruction u = v mod 2);
  5. the only idempotents are 0 and 1, so the ring is not Z x Z;
  6. among the rational integers, only +-2 are irreducible;
  7. the twist t is a unit of order two, and it differs from the sign -1
     (for example 6t is neither 6 nor -6).
"""

from __future__ import annotations

from itertools import product
from typing import Dict, List, Tuple

Elt = Tuple[int, int]  # (a, b) stands for a + b t


def mul(x: Elt, y: Elt) -> Elt:
    return (x[0] * y[0] + x[1] * y[1], x[0] * y[1] + x[1] * y[0])


def norm(x: Elt) -> int:
    return x[0] * x[0] - x[1] * x[1]


def show(x: Elt) -> str:
    a, b = x
    if b == 0:
        return str(a)
    mag = "t" if abs(b) == 1 else f"{abs(b)}t"
    if a == 0:
        return mag if b > 0 else f"-{mag}"
    return f"{a} {'+' if b > 0 else '-'} {mag}"


def is_prime(m: int) -> bool:
    m = abs(m)
    if m < 2:
        return False
    if m % 2 == 0:
        return m == 2
    k = 3
    while k * k <= m:
        if m % k == 0:
            return False
        k += 2
    return True


def main(R: int = 20) -> None:
    box: List[Elt] = [(a, b) for a in range(-R, R + 1) for b in range(-R, R + 1)]

    print(f"Auditing the twist ring on the box |a|, |b| <= {R}  "
          f"({len(box)} elements).\n")

    # 1. Multiplicativity of the norm (on a smaller sub-box, all pairs).
    small = [(a, b) for a in range(-6, 7) for b in range(-6, 7)]
    assert all(norm(mul(x, y)) == norm(x) * norm(y) for x, y in product(small, small))
    print(f"1. norm multiplicativity: verified on all {len(small)**2} pairs "
          f"with |a|,|b| <= 6")

    # 2. Units.
    units = [x for x in box if abs(norm(x)) == 1]
    assert set(units) == {(1, 0), (-1, 0), (0, 1), (0, -1)}
    assert all(mul(u, u) == (1, 0) for u in units)
    print(f"2. unit group = {{{', '.join(show(u) for u in units)}}}; every unit squares "
          f"to 1, so it is the Klein four-group (Z/2)^2")

    # 3. Zero divisors.
    zds = sorted((x for x in box if x != (0, 0) and norm(x) == 0),
                 key=lambda x: (abs(x[0]), x[0], x[1]))
    assert all(abs(x[0]) == abs(x[1]) for x in zds)
    for x in zds:
        w = (1, 1) if x[0] + x[1] == 0 else (1, -1)
        assert mul(x, w) == (0, 0)
    print(f"3. zero divisors: {len(zds)} nonzero elements, all with a = ±b; annihilated "
          f"by 1 ∓ t. Example: ({show(zds[0])})·({show((1,1) if zds[0][0]+zds[0][1]==0 else (1,-1))}) = 0")

    # 4. Parity obstruction.
    assert not [x for x in box if abs(norm(x)) == 2]
    counts: Dict[str, int] = {"odd": 0, "div4": 0, "other": 0}
    for x in box:
        n = norm(x)
        if n % 2 != 0:
            counts["odd"] += 1
        elif n % 4 == 0:
            counts["div4"] += 1
        else:
            counts["other"] += 1
    print(f"4. norms: {counts['odd']} odd, {counts['div4']} divisible by 4, "
          f"{counts['other']} of the form 2 mod 4  →  norm ±2 is impossible")

    # 5. Idempotents.
    idem = [x for x in box if mul(x, x) == x]
    assert set(idem) == {(0, 0), (1, 0)}
    print(f"5. idempotents: {', '.join(show(e) for e in idem)} only  →  the ring is not "
          f"Z × Z (which has the idempotent (1,0))")

    # 6. Irreducible rational integers.
    def reducible_int(n: int) -> bool:
        if n == 0:
            return True
        if abs(n) == 1:
            return True  # a unit, hence not irreducible
        for x in box:
            if abs(norm(x)) <= 1 or x == (0, 0):
                continue
            for y in box:
                if abs(norm(y)) <= 1 or y == (0, 0):
                    continue
                if mul(x, y) == (n, 0):
                    return True
        return False

    irreducible_ints = [n for n in range(-8, 9) if not reducible_int(n)]
    assert irreducible_ints == [-2, 2]
    print(f"6. rational integers in [-8, 8] that are irreducible: {irreducible_ints}")
    for n in (3, 5, 7, 9):
        k = (n - 1) // 2
        print(f"     {n} = ({show((k+1, k))})({show((k+1, -k))})"
              f"   norms {norm((k+1,k))}, {norm((k+1,-k))}"
              f"   {'both irreducible' if is_prime(n) else 'norms composite'}")

    # 7. The twist versus the sign.
    six, six_t = (6, 0), mul((0, 1), (6, 0))
    assert six_t != six and six_t != (-6, 0)
    print(f"7. 6 = {show(six)}, −6 = {show((-6,0))}, 6t = {show(six_t)} — three distinct "
          f"elements: the twist is not the sign.")
    print(f"   6 factors as 2 · (2 + t) · (2 − t): "
          f"{mul((2,0), mul((2,1),(2,-1))) == six}")

    print("\nAll assertions passed.")


if __name__ == "__main__":
    main()

