"""Factorisation of a rational integer inside the twist ring Z[t]/(t^2 - 1).

The algorithm rests on three facts about the norm N(a + bt) = a^2 - b^2:
  (i)   N is multiplicative;
  (ii)  no element has norm +-2 (parity obstruction), so N = 4 forces
        irreducibility and the rational prime 2 stays irreducible;
  (iii) every odd integer splits as 2k+1 = ((k+1) + kt)((k+1) - kt), whose
        factors have norm 2k+1 and are therefore irreducible when 2k+1 is prime.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import List, Tuple


@dataclass(frozen=True)
class TwistInt:
    """The element a + b*t of Z[t]/(t^2 - 1)."""

    a: int
    b: int

    def __mul__(self, other: "TwistInt") -> "TwistInt":
        return TwistInt(self.a * other.a + self.b * other.b,
                        self.a * other.b + self.b * other.a)

    def characters(self) -> Tuple[int, int]:
        """(chi_+(z), chi_-(z)) = (a+b, a-b); always congruent modulo 2."""
        return (self.a + self.b, self.a - self.b)

    def norm(self) -> int:
        u, v = self.characters()
        return u * v

    def is_unit(self) -> bool:
        return self.norm() in (1, -1)

    def __str__(self) -> str:
        if self.b == 0:
            return str(self.a)
        mag = "t" if abs(self.b) == 1 else f"{abs(self.b)}t"
        if self.a == 0:
            return mag if self.b > 0 else f"-{mag}"
        return f"({self.a} {'+' if self.b > 0 else '-'} {mag})"


def factor_rational_integer(n: int) -> Tuple[TwistInt, List[TwistInt]]:
    """Return (unit, factors) with unit * prod(factors) = n in Z[t]/(t^2 - 1).

    Complexity: O(sqrt(n)) by trial division, plus O(1) per emitted factor.
    The number of irreducible factors of n = +-2^e * m (m odd) is e + 2*Omega(m):
    odd primes split into conjugate pairs, the prime 2 does not.
    """
    one = TwistInt(1, 0)
    if n == 0:
        # Zero itself factors nontrivially: 0 = (1 + t)(1 - t).
        return one, [TwistInt(1, 1), TwistInt(1, -1)]
    if abs(n) == 1:
        return TwistInt(n, 0), []
    unit = one if n > 0 else TwistInt(-1, 0)
    m = abs(n)
    factors: List[TwistInt] = []
    while m % 2 == 0:
        factors.append(TwistInt(2, 0))  # irreducible: N = 4 and norm +-2 is impossible
        m //= 2
    p = 3
    while p * p <= m:
        while m % p == 0:
            k = (p - 1) // 2
            factors.append(TwistInt(k + 1, k))   # norm p
            factors.append(TwistInt(k + 1, -k))  # norm p
            m //= p
        p += 2
    if m > 1:
        k = (m - 1) // 2
        factors.append(TwistInt(k + 1, k))
        factors.append(TwistInt(k + 1, -k))
    return unit, factors


def render(n: int) -> str:
    unit, factors = factor_rational_integer(n)
    product = unit
    for f in factors:
        product = product * f
    assert product == TwistInt(n, 0), "factorisation must reproduce n"
    pieces = ([] if unit == TwistInt(1, 0) else [str(unit)]) + [str(f) for f in factors]
    body = " * ".join(pieces) if pieces else "1"
    norms = ", ".join(str(f.norm()) for f in factors)
    return f"{n} = {body}    [{len(factors)} irreducible factor(s); norms: {norms}]"


if __name__ == "__main__":
    for n in (0, 1, -1, 2, -2, 3, 6, -6, 12, 105, 1024):
        print(render(n))

"""Certified localisation of the forced zero of a Möbius section.

A section of the Möbius line bundle over the circle is a continuous function
f : R -> R with f(x + 1) = -f(x). Because the endpoint values of any window
[a, a+1] are exact negatives of one another, the intermediate value theorem
guarantees a zero inside the window. The bisection below turns that existence
statement into a certified numerical enclosure: after k steps the zero is
localised to an interval of width 2^{-k} on whose endpoints f has opposite
signs (a sign-change certificate).

Complexity: k function evaluations for an enclosure of width 2^{-k}, i.e.
O(log(1/eps)) evaluations for accuracy eps -- independent of the section.
"""

from __future__ import annotations

from typing import Callable, List, Tuple


def antiperiodicity_defect(f: Callable[[float], float], samples: List[float]) -> float:
    """max |f(x+1) + f(x)| over the samples; zero iff f is antiperiodic there."""
    return max(abs(f(x + 1.0) + f(x)) for x in samples)


def enclose_zero(f: Callable[[float], float], a: float,
                 steps: int = 60) -> Tuple[float, float]:
    """Return an interval [lo, hi] subset of [a, a+1] enclosing a zero of f.

    Requires f continuous and antiperiodic with period-shift 1; then f(a+1) = -f(a),
    so the initial endpoints already straddle zero and the invariant
    sign(f(lo)) != sign(f(hi)) is maintained throughout.
    """
    lo, hi = a, a + 1.0
    flo, fhi = f(lo), f(hi)
    if flo == 0.0:
        return (lo, lo)
    if fhi == 0.0:
        return (hi, hi)
    for _ in range(steps):
        mid = 0.5 * (lo + hi)
        fmid = f(mid)
        if fmid == 0.0:
            return (mid, mid)
        if (flo < 0.0) != (fmid < 0.0):
            hi, fhi = mid, fmid
        else:
            lo, flo = mid, fmid
    return (lo, hi)


def zeros_in(f: Callable[[float], float], start: int, count: int) -> List[float]:
    """One certified zero in each of the windows [start+k, start+k+1], k < count."""
    out: List[float] = []
    for k in range(count):
        lo, hi = enclose_zero(f, float(start + k))
        out.append(0.5 * (lo + hi))
    return out


if __name__ == "__main__":
    import math

    # Any combination of odd harmonics is a Möbius section.
    f = lambda x: (math.cos(math.pi * x) + 0.4 * math.cos(3 * math.pi * x)
                   - 0.3 * math.sin(5 * math.pi * x))
    grid = [0.0, 0.13, 0.5, 0.77, 1.9, -0.4]
    print(f"antiperiodicity defect: {antiperiodicity_defect(f, grid):.2e}")
    for z in zeros_in(f, -2, 6):
        print(f"zero at x = {z:+.10f}   f(x) = {f(z):+.2e}")
